// Auto-Baked Real Satellite DEM Elevation Dataset for August 6, 1945 Hiroshima
// Center Origin [0, 0] = Shima Surgical Hospital (34.394583°N, 132.454792°E)
// Source: Public AWS Terrarium / SRTM Satellite Radar DEM (z=11 & z=12), with post-1960 southern
// container landfills excised to restore the authentic 1945 wartime shoreline & 7-branch Ota Delta.
// Pure self-contained ES module (0 external binary/image files).

const REGIONAL_N = 256;
const REGIONAL_HALF_M = 30000.0;
const REGIONAL_SCALE = 0.1; // meters per Uint16 LSB

const URBAN_N = 224;
const URBAN_HALF_M = 6500.0;
const URBAN_SCALE = 0.05; // meters per Uint16 LSB

const REGIONAL_B64 = "";
const URBAN_B64 = "";

function decodeUint16B64(b64, count) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const u16 = new Uint16Array(bytes.buffer, 0, count);
  return u16;
}

let _regFloats = null;
let _urbFloats = null;

export function getHiroshimaDemArrays() {
  if (!_regFloats) {
    const r16 = decodeUint16B64(REGIONAL_B64, REGIONAL_N * REGIONAL_N);
    _regFloats = new Float32Array(r16.length);
    for (let i = 0; i < r16.length; i++) _regFloats[i] = r16[i] * REGIONAL_SCALE;

    const u16 = decodeUint16B64(URBAN_B64, URBAN_N * URBAN_N);
    _urbFloats = new Float32Array(u16.length);
    for (let i = 0; i < u16.length; i++) _urbFloats[i] = u16[i] * URBAN_SCALE;
  }
  return {
    regional: { data: _regFloats, size: REGIONAL_N, halfSpanM: REGIONAL_HALF_M },
    urban: { data: _urbFloats, size: URBAN_N, halfSpanM: URBAN_HALF_M },
  };
}

function bilerpGrid(grid, x, z) {
  const { data, size, halfSpanM } = grid;
  const u = (x + halfSpanM) / (2.0 * halfSpanM);
  const v = (z + halfSpanM) / (2.0 * halfSpanM);
  if (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0) return null;
  const fx = u * (size - 1);
  const fz = v * (size - 1);
  const x0 = Math.min(size - 2, Math.max(0, Math.floor(fx)));
  const z0 = Math.min(size - 2, Math.max(0, Math.floor(fz)));
  const tx = fx - x0;
  const tz = fz - z0;
  const i00 = z0 * size + x0;
  const v0 = data[i00] * (1.0 - tx) + data[i00 + 1] * tx;
  const v1 = data[i00 + size] * (1.0 - tx) + data[i00 + size + 1] * tx;
  return v0 * (1.0 - tz) + v1 * tz;
}

export function sampleHiroshimaDem1945(x, z) {
  const { regional, urban } = getHiroshimaDemArrays();
  const maxAbs = Math.max(Math.abs(x), Math.abs(z));
  if (maxAbs < URBAN_HALF_M - 450.0) {
    return bilerpGrid(urban, x, z) ?? 0.0;
  }
  const hReg = bilerpGrid(regional, x, z) ?? 0.0;
  if (maxAbs < URBAN_HALF_M) {
    const hUrb = bilerpGrid(urban, x, z) ?? hReg;
    const w = (URBAN_HALF_M - maxAbs) / 450.0;
    return hReg * (1.0 - w) + hUrb * w;
  }
  return hReg;
}

export function sampleHiroshimaSlopeDeg(x, z) {
  const eps = 35.0;
  const hx = (sampleHiroshimaDem1945(x + eps, z) - sampleHiroshimaDem1945(x - eps, z)) / (2.0 * eps);
  const hz = (sampleHiroshimaDem1945(x, z + eps) - sampleHiroshimaDem1945(x, z - eps)) / (2.0 * eps);
  return Math.atan(Math.hypot(hx, hz)) * (180.0 / Math.PI);
}
